import { Session } from "node:inspector";
const enabled = Deno.env.get("WRITER_FIT_PROFILE") === "1";
const session = new Session();
if (enabled) session.connect();
const post = (method: string, params = {}) => new Promise<any>((resolve, reject) => session.post(method, params, (err, result) => err ? reject(err) : resolve(result)));
export async function start() {
  if (!enabled) return;
  await post("Profiler.enable");
  await post("Profiler.setSamplingInterval", { interval: 500 });
  await post("Profiler.start");
}
export async function stop(name: string) {
  if (!enabled) return;
  const { profile } = await post("Profiler.stop");
  await Deno.writeTextFile(Deno.env.get("WRITER_FIT_OUT") + "-" + name + ".cpuprofile", JSON.stringify(profile));
}

export const errors: unknown[] = [];
export function recordError(error: any) { errors.push({name:error.name, message:error.message, refusals:error.refusals}); }

